challenge.solution:
import re

def slugify(title):
    cleaned = title.lower().replace("'", "")
    return "-".join(re.findall(r"[a-z0-9]+", cleaned))

def test_basic():
    assert slugify("Hello World") == "hello-world"

def test_extra_spaces():
    assert slugify("  Many   spaces here ") == "many-spaces-here"

def test_punctuation():
    assert slugify("What's new?") == "whats-new"

def test_empty():
    assert slugify("") == ""

for test in [test_basic, test_extra_spaces, test_punctuation, test_empty]:
    try:
        test()
        print("PASS", test.__name__)
    except AssertionError:
        print("FAIL", test.__name__)

